"use client";

import { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase/client";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Mic, Upload, FileText, Play, CheckCircle2, Loader2, List } from "lucide-react";
import Link from "next/link";
import Papa from "papaparse";

function Alert({ title, message }: { title: string; message: string }) {
  return (
    <div
      className="bg-destructive/10 border border-destructive/50 text-destructive dark:border-destructive/80 rounded-lg p-4"
      role="alert"
    >
      <h5 className="font-bold">{title}</h5>
      <p className="text-sm">{message}</p>
    </div>
  );
}

export function GeneratorPage({ user }: { user: any }) {
  const [activeTab, setActiveTab] = useState<"single" | "bulk">("single");
  const [formData, setFormData] = useState({
    address: "",
    beds: "",
    baths: "",
    sqft: "",
    price: "",
    features: "",
    tone: "Professional",
  });
  const [generatedListing, setGeneratedListing] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isQuotaExceeded, setIsQuotaExceeded] = useState(false);
  const [styles, setStyles] = useState<any[]>([]);
  const [selectedStyleId, setSelectedStyleId] = useState<string>("");

  // Bulk Mode State
  const [csvData, setCsvData] = useState<any[]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [mappings, setMappings] = useState({
    address: "",
    price: "",
    features: ""
  });
  const [bulkResults, setBulkResults] = useState<{ address: string; listing: string; status: "pending" | "processing" | "completed" | "error" }[]>([]);
  const [currentBulkIndex, setCurrentBulkIndex] = useState(-1);

  const supabase = createClient();

  useEffect(() => {
    async function loadStyles() {
      if (user) {
        const { data } = await supabase.from("voice_profiles").select("*");
        setStyles(data || []);
      }
    }
    loadStyles();
  }, [user]);

  const handleUpgrade = async () => {
    setIsLoading(true);
    try {
      const response = await fetch("/api/checkout", { method: "POST" });
      const data = await response.json();
      if (data.url) {
        window.location.href = data.url;
      } else {
        throw new Error("Failed to create checkout session");
      }
    } catch (err: any) {
      setError(err.message);
      setIsLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { id, value } = e.target;
    setFormData((prev) => ({ ...prev, [id]: value }));
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setIsLoading(true);
    setGeneratedListing("");
    setError(null);
    setIsQuotaExceeded(false);

    try {
      const response = await fetch("/api/generate-listing", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...formData, styleId: selectedStyleId }),
      });

      const data = await response.json();
      if (!response.ok) {
        if (data.isQuotaExceeded) setIsQuotaExceeded(true);
        throw new Error(data.error || "Something went wrong.");
      }
      setGeneratedListing(data.listing);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  // Bulk Mode Handlers
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          setCsvHeaders(results.meta.fields || []);
          setCsvData(results.data);
          if (results.meta.fields?.length) {
            setMappings({
              address: results.meta.fields[0],
              price: results.meta.fields[1] || "",
              features: results.meta.fields[2] || ""
            });
          }
        },
      });
    }
  };

  const startBulkGeneration = async () => {
    if (!mappings.address || csvData.length === 0) return;
    
    setIsLoading(true);
    setError(null);
    const initialResults = csvData.map(row => ({
      address: row[mappings.address],
      price: mappings.price ? row[mappings.price] : "",
      features: mappings.features ? row[mappings.features] : "",
      listing: "",
      status: "pending" as const
    }));
    setBulkResults(initialResults.map(r => ({ address: r.address, listing: "", status: "pending" as const })));

    for (let i = 0; i < initialResults.length; i++) {
      setCurrentBulkIndex(i);
      setBulkResults(prev => prev.map((res, idx) => i === idx ? { ...res, status: "processing" } : res));

      try {
        const response = await fetch("/api/generate-listing", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ 
            address: initialResults[i].address,
            price: initialResults[i].price,
            features: initialResults[i].features,
            tone: formData.tone,
            styleId: selectedStyleId 
          }),
        });

        const data = await response.json();
        if (!response.ok) {
          if (data.isQuotaExceeded) {
            setIsQuotaExceeded(true);
            setIsLoading(false);
            return;
          }
          throw new Error(data.error);
        }

        setBulkResults(prev => prev.map((res, idx) => i === idx ? { ...res, listing: data.listing, status: "completed" } : res));
      } catch (err) {
        setBulkResults(prev => prev.map((res, idx) => i === idx ? { ...res, status: "error" } : res));
      }
    }
    setIsLoading(false);
    setCurrentBulkIndex(-1);
  };

  const downloadBulkResults = () => {
    const csv = Papa.unparse(bulkResults.map(r => ({
      Address: r.address,
      Generated_Listing: r.listing
    })));
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.body.appendChild(document.createElement("a"));
    link.href = URL.createObjectURL(blob);
    link.download = `bulk_listings_${new Date().getTime()}.csv`;
    link.click();
    link.remove();
  };

  if (!user) {
    return (
      <div className="flex flex-col items-center justify-center w-full flex-1 px-20 text-center py-20">
        <h1 className="text-4xl font-bold mb-4">GHOSTFORCE REALTY</h1>
        <p className="mb-6">Log in to automate your property marketing suite.</p>
        <Button asChild><Link href="/login">Log In</Link></Button>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center w-full p-4 md:p-8 max-w-6xl mx-auto" suppressHydrationWarning>
      <div className="flex items-center justify-between w-full mb-8">
        <div>
          <h1 className="text-4xl font-bold italic tracking-tighter">GHOSTFORCE REALTY</h1>
          <p className="text-muted-foreground uppercase text-xs tracking-widest font-semibold">Inventory Description Engine</p>
        </div>
        <Button variant="ghost" asChild><Link href="/voice-lab"><Mic className="mr-2 h-4 w-4" /> Voice Lab</Link></Button>
      </div>

      {isQuotaExceeded && (
        <Card className="mb-8 border-primary bg-primary/5 w-full">
          <CardHeader>
            <CardTitle>API Limit Reached</CardTitle>
            <CardDescription>
              The AI model has reached its generation limit. If you are a free user, please wait 24 hours or upgrade. 
              If you are a Pro user, this may be a temporary provider bottleneck.
            </CardDescription>
          </CardHeader>
          <CardFooter>
            <Button onClick={handleUpgrade} className="w-full">Upgrade to Pro for $29/mo</Button>
          </CardFooter>
        </Card>
      )}

      {error && <div className="w-full mb-4"><Alert title="Error" message={error} /></div>}

      <div className="w-full space-y-8">
        <div className="flex bg-muted p-1 rounded-lg w-fit mx-auto">
          <button onClick={() => setActiveTab("single")} className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${activeTab === "single" ? "bg-background shadow-sm" : "hover:text-primary"}`}>Single Listing</button>
          <button onClick={() => setActiveTab("bulk")} className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${activeTab === "bulk" ? "bg-background shadow-sm" : "hover:text-primary"}`}>Bulk Mode (CSV)</button>
        </div>

        {activeTab === "single" ? (
          <div className="max-w-3xl mx-auto w-full">
            <form onSubmit={handleSubmit}>
              <Card>
                <CardHeader><CardTitle>Property Details</CardTitle></CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex flex-col space-y-1.5">
                    <Label htmlFor="style">Writing Voice</Label>
                    <select id="style" className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm" value={selectedStyleId} onChange={(e) => setSelectedStyleId(e.target.value)}>
                      <option value="">Default AI Voice</option>
                      {styles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex flex-col space-y-1.5">
                      <Label htmlFor="address">Address</Label>
                      <Input id="address" placeholder="123 Maple St" value={formData.address} onChange={handleInputChange} />
                    </div>
                    <div className="flex flex-col space-y-1.5">
                      <Label htmlFor="price">Price</Label>
                      <Input id="price" placeholder="$850,000" value={formData.price} onChange={handleInputChange} />
                    </div>
                  </div>
                  <div className="flex flex-col space-y-1.5">
                    <Label htmlFor="features">Features</Label>
                    <Textarea id="features" placeholder="Pool, renovated kitchen..." value={formData.features} onChange={handleInputChange} />
                  </div>
                </CardContent>
                <CardFooter className="flex justify-between">
                  <p className="text-xs text-muted-foreground">Logged in: {user.email}</p>
                  <Button type="submit" disabled={isLoading || !formData.address || isQuotaExceeded}>
                    {isLoading ? "Writing..." : "Generate Listing"}
                  </Button>
                </CardFooter>
              </Card>
            </form>
            {generatedListing && (
              <Card className="mt-8">
                <CardHeader><CardTitle>Generated Description</CardTitle></CardHeader>
                <CardContent><Textarea readOnly className="h-80 text-base bg-muted/20" value={generatedListing} /></CardContent>
              </Card>
            )}
          </div>
        ) : (
          <div className="w-full grid grid-cols-1 lg:grid-cols-3 gap-8">
            <Card className="h-fit">
              <CardHeader><CardTitle>Bulk Setup</CardTitle></CardHeader>
              <CardContent className="space-y-6">
                <div className="space-y-2">
                  <Label>1. Upload CSV</Label>
                  <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-lg cursor-pointer bg-muted/5 hover:bg-muted/10 transition-colors">
                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                      <Upload className="w-8 h-8 mb-3 text-muted-foreground" />
                      <p className="text-sm text-muted-foreground">Click to upload CSV</p>
                    </div>
                    <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
                  </label>
                </div>
                {csvHeaders.length > 0 && (
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label>2. Map Fields</Label>
                      <div className="space-y-2">
                        <Label className="text-xs">Address Column</Label>
                        <select className="flex h-8 w-full rounded-md border text-xs bg-transparent px-2" value={mappings.address} onChange={(e) => setMappings({...mappings, address: e.target.value})}>
                          {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                        <Label className="text-xs">Price Column</Label>
                        <select className="flex h-8 w-full rounded-md border text-xs bg-transparent px-2" value={mappings.price} onChange={(e) => setMappings({...mappings, price: e.target.value})}>
                          <option value="">(None)</option>
                          {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                        <Label className="text-xs">Features Column</Label>
                        <select className="flex h-8 w-full rounded-md border text-xs bg-transparent px-2" value={mappings.features} onChange={(e) => setMappings({...mappings, features: e.target.value})}>
                          <option value="">(None)</option>
                          {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label>3. Select Voice</Label>
                      <select 
                        className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm"
                        value={selectedStyleId}
                        onChange={(e) => setSelectedStyleId(e.target.value)}
                      >
                        <option value="">Default AI Voice</option>
                        {styles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-4">
                      <Button className="w-full" onClick={startBulkGeneration} disabled={isLoading || isQuotaExceeded}>
                        <Play className="mr-2 h-4 w-4" /> Start Bulk Run
                      </Button>
                      
                      {bulkResults.some(r => r.status === "completed") && (
                        <Button variant="outline" className="w-full" onClick={downloadBulkResults}>
                          <FileText className="mr-2 h-4 w-4" /> Download Results (.csv)
                        </Button>
                      )}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>

            <div className="lg:col-span-2 space-y-4">
              <h3 className="font-semibold text-xl flex items-center"><List className="mr-2 h-5 w-5" /> Listing Queue ({bulkResults.length})</h3>
              <div className="space-y-4 max-h-[800px] overflow-y-auto">
                {bulkResults.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-64 border-2 border-dashed rounded-xl text-muted-foreground bg-muted/5">
                    <FileText className="h-12 w-12 mb-4 opacity-20" />
                    <p>Upload a CSV to process properties.</p>
                  </div>
                ) : (
                  bulkResults.map((res, i) => (
                    <Card key={i} className={i === currentBulkIndex ? "border-primary shadow-md" : ""}>
                      <CardHeader className="py-4">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-base truncate">{res.address}</CardTitle>
                          {res.status === "completed" && <CheckCircle2 className="text-green-500 h-5 w-5" />}
                          {res.status === "processing" && <Loader2 className="text-primary h-5 w-5 animate-spin" />}
                        </div>
                      </CardHeader>
                      {res.listing && <CardContent className="pb-4 pt-0"><Textarea readOnly className="h-32 text-xs bg-muted/30" value={res.listing} /></CardContent>}
                    </Card>
                  ))
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
